figure.artwork:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:ietf:params:json-schema:child-rendering-candidate:00",
  "title": "RestrictedContentCandidate",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "candidate_act_id",
    "act_type",
    "content",
    "recipient_context",
    "policy_context",
    "render_request",
    "freshness",
    "finality_sink"
  ],
  "properties": {
    "version": {
      "type": "string",
      "const": "1.0"
    },
    "candidate_act_id": {
      "type": "string",
      "minLength": 16,
      "maxLength": 128
    },
    "act_type": {
      "type": "string",
      "enum": [
        "RENDER_VIDEO",
        "RENDER_IMAGE",
        "PLAY_AUDIO",
        "RENDER_INTERACTIVE",
        "RENDER_GENERATED_MEDIA",
        "CAST_PROTECTED_CONTENT",
        "MIRROR_PROTECTED_CONTENT"
      ]
    },
    "content": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "content_id",
        "content_digest",
        "content_class",
        "classification_source",
        "protection_state"
      ],
      "properties": {
        "content_id": {
          "type": "string",
          "maxLength": 256
        },
        "content_digest": {
          "type": "string",
          "pattern": "^sha256:[0-9a-fA-F]{64}$"
        },
        "content_class": {
          "type": "string",
          "enum": [
            "ADULT_SEXUAL_CONTENT",
            "SEXUALLY_EXPLICIT_CONTENT",
            "AGE_RESTRICTED_VIDEO",
            "AGE_RESTRICTED_AUDIO",
            "AGE_RESTRICTED_INTERACTIVE",
            "AGE_RESTRICTED_GENERATED_MEDIA",
            "OTHER_RESTRICTED"
          ]
        },
        "classification_source": {
          "type": "string",
          "maxLength": 256
        },
        "classification_confidence": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "protection_state": {
          "type": "string",
          "enum": [
            "ENCRYPTED",
            "KEY_WITHHELD",
            "PROTECTED_SURFACE_ONLY",
            "NON_RENDERABLE_BUFFER",
            "OTHER_PROTECTED"
          ]
        },
        "origin_service": {
          "type": "string",
          "maxLength": 256
        },
        "generation_model_id": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 256
        }
      }
    },
    "recipient_context": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "recipient_context_id",
        "eligibility_state",
        "eligibility_evidence_ref"
      ],
      "properties": {
        "recipient_context_id": {
          "type": "string",
          "maxLength": 256
        },
        "eligibility_state": {
          "type": "string",
          "enum": [
            "ELIGIBLE",
            "NOT_ELIGIBLE",
            "UNKNOWN",
            "EXPIRED",
            "REVOKED"
          ]
        },
        "eligibility_evidence_ref": {
          "type": "string",
          "maxLength": 512
        },
        "age_threshold_claim": {
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "OVER_18",
            "OVER_LOCAL_THRESHOLD",
            null
          ]
        },
        "parental_policy_ref": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 512
        },
        "privacy_preserving_proof": {
          "type": "boolean"
        }
      }
    },
    "policy_context": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "jurisdiction",
        "policy_id",
        "policy_epoch",
        "revocation_epoch"
      ],
      "properties": {
        "jurisdiction": {
          "type": "string",
          "maxLength": 64
        },
        "policy_id": {
          "type": "string",
          "maxLength": 256
        },
        "policy_epoch": {
          "type": "integer",
          "minimum": 0
        },
        "revocation_epoch": {
          "type": "integer",
          "minimum": 0
        },
        "parental_control_state": {
          "type": "string",
          "enum": [
            "ALLOW",
            "DENY",
            "NOT_APPLICABLE",
            "UNKNOWN"
          ]
        },
        "platform_policy_state": {
          "type": "string",
          "enum": [
            "ALLOW",
            "DENY",
            "REVIEW",
            "UNKNOWN"
          ]
        }
      }
    },
    "render_request": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "device_id",
        "application_id",
        "render_mode",
        "output_targets"
      ],
      "properties": {
        "device_id": {
          "type": "string",
          "maxLength": 256
        },
        "application_id": {
          "type": "string",
          "maxLength": 256
        },
        "component_id": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 256
        },
        "render_mode": {
          "type": "string",
          "enum": [
            "LOCAL_DISPLAY",
            "LOCAL_AUDIO",
            "XR_DISPLAY",
            "CAST",
            "MIRROR",
            "REMOTE_DISPLAY"
          ]
        },
        "output_targets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "enum": [
              "DISPLAY",
              "SPEAKER",
              "HEADSET",
              "XR_COMPOSITOR",
              "CAST_SINK",
              "MIRROR_SINK"
            ]
          }
        },
        "requested_resolution": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 64
        },
        "requested_audio": {
          "type": "boolean"
        },
        "requested_decryption": {
          "type": "boolean"
        }
      }
    },
    "freshness": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "nonce",
        "created_at",
        "expires_at"
      ],
      "properties": {
        "nonce": {
          "type": "string",
          "minLength": 16,
          "maxLength": 256
        },
        "created_at": {
          "type": "string",
          "format": "date-time"
        },
        "expires_at": {
          "type": "string",
          "format": "date-time"
        },
        "session_id": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 256
        }
      }
    },
    "finality_sink": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sink_id",
        "sink_type"
      ],
      "properties": {
        "sink_id": {
          "type": "string",
          "maxLength": 256
        },
        "sink_type": {
          "type": "string",
          "enum": [
            "CONTENT_KEY_RELEASE",
            "DECRYPTION_GATE",
            "MEDIA_DECODER_GATE",
            "GPU_COMPOSITOR_GATE",
            "PROTECTED_SURFACE_GATE",
            "DISPLAY_ENABLE_GATE",
            "AUDIO_OUTPUT_GATE",
            "CAST_GATE",
            "MIRROR_GATE"
          ]
        },
        "attestation_ref": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 512
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "RenderingPolicyDecision",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "candidate_act_id",
    "decision",
    "decision_id",
    "validated_policy_epoch",
    "validated_revocation_epoch",
    "permitted_effects",
    "denial_reasons"
  ],
  "properties": {
    "candidate_act_id": {
      "type": "string"
    },
    "decision": {
      "type": "string",
      "enum": [
        "ALLOW_RENDER",
        "DENY_RENDER",
        "ALLOW_RESTRICTED_MODE",
        "REQUIRE_REVALIDATION"
      ]
    },
    "decision_id": {
      "type": "string"
    },
    "validated_policy_epoch": {
      "type": "integer",
      "minimum": 0
    },
    "validated_revocation_epoch": {
      "type": "integer",
      "minimum": 0
    },
    "permitted_effects": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "RELEASE_CONTENT_KEY",
          "DECRYPT",
          "DECODE",
          "CREATE_PROTECTED_SURFACE",
          "COMPOSITE",
          "DISPLAY",
          "PLAY_AUDIO",
          "CAST",
          "MIRROR"
        ]
      }
    },
    "denial_reasons": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "RECIPIENT_NOT_ELIGIBLE",
          "ELIGIBILITY_UNKNOWN",
          "ELIGIBILITY_EXPIRED",
          "PARENTAL_POLICY_DENY",
          "PLATFORM_POLICY_DENY",
          "CONTENT_CLASS_MISMATCH",
          "POLICY_EPOCH_STALE",
          "REVOCATION_EPOCH_STALE",
          "NONCE_REPLAY",
          "DEVICE_MISMATCH",
          "APPLICATION_MISMATCH",
          "SINK_MISMATCH",
          "OUTPUT_TARGET_NOT_PERMITTED",
          "ATTESTATION_FAILURE",
          "AUTHORITY_EXPIRED"
        ]
      }
    },
    "validation_evidence_ref": {
      "type": "string"
    },
    "decision_expires_at": {
      "type": "string",
      "format": "date-time"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "RenderingFinalityAuthority",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "authority_id",
    "candidate_act_id",
    "candidate_digest",
    "validation_evidence_ref",
    "permitted_effects",
    "sink_id",
    "policy_epoch",
    "revocation_epoch",
    "nonce",
    "issued_at",
    "expires_at",
    "consumption"
  ],
  "properties": {
    "authority_id": {
      "type": "string"
    },
    "candidate_act_id": {
      "type": "string"
    },
    "candidate_digest": {
      "type": "string",
      "pattern": "^sha256:[0-9a-fA-F]{64}$"
    },
    "validation_evidence_ref": {
      "type": "string"
    },
    "permitted_effects": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string"
      }
    },
    "content_digest": {
      "type": "string",
      "pattern": "^sha256:[0-9a-fA-F]{64}$"
    },
    "recipient_context_id": {
      "type": "string"
    },
    "device_id": {
      "type": "string"
    },
    "application_id": {
      "type": "string"
    },
    "sink_id": {
      "type": "string"
    },
    "sink_type": {
      "type": "string"
    },
    "policy_epoch": {
      "type": "integer"
    },
    "revocation_epoch": {
      "type": "integer"
    },
    "nonce": {
      "type": "string"
    },
    "issued_at": {
      "type": "string",
      "format": "date-time"
    },
    "expires_at": {
      "type": "string",
      "format": "date-time"
    },
    "consumption": {
      "type": "string",
      "enum": [
        "SINGLE_USE",
        "FRAME_WINDOW",
        "SESSION_BOUND"
      ]
    },
    "max_frame_count": {
      "type": [
        "integer",
        "null"
      ],
      "minimum": 1
    },
    "max_duration_ms": {
      "type": [
        "integer",
        "null"
      ],
      "minimum": 1
    },
    "signature_or_mac": {
      "type": "string"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "RenderSinkVerifyRequest",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "candidate",
    "authority",
    "sink_runtime_state"
  ],
  "properties": {
    "candidate": {
      "$ref": "urn:ietf:params:json-schema:child-rendering-candidate:00"
    },
    "authority": {
      "type": "object"
    },
    "sink_runtime_state": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sink_id",
        "current_policy_epoch",
        "current_revocation_epoch",
        "authority_consumed",
        "device_attestation_state",
        "output_path"
      ],
      "properties": {
        "sink_id": {
          "type": "string"
        },
        "current_policy_epoch": {
          "type": "integer"
        },
        "current_revocation_epoch": {
          "type": "integer"
        },
        "authority_consumed": {
          "type": "boolean"
        },
        "device_attestation_state": {
          "type": "string",
          "enum": [
            "VALID",
            "INVALID",
            "UNKNOWN"
          ]
        },
        "output_path": {
          "type": "string",
          "enum": [
            "DISPLAY",
            "AUDIO",
            "XR",
            "CAST",
            "MIRROR"
          ]
        },
        "screen_capture_active": {
          "type": "boolean"
        },
        "external_display_attached": {
          "type": "boolean"
        }
      }
    }
  }
}
